import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md"}'),n={name:"guide/glossary.md"};function i(l,e,s,h,d,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Terms you&#39;ll encounter when using VERA, explained for day-to-day use.</p><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="agile-project" tabindex="-1">Agile project <a class="header-anchor" href="#agile-project" aria-label="Permalink to &quot;Agile project&quot;">​</a></h3><p>A project type where work is broken into time-boxed sprints, each with its own fee and hours budget. Revenue is recognised when a sprint is marked active. When one sprint closes, the next opens. See <a href="./projects.html">Projects and tasks</a>.</p><h3 id="alert-threshold" tabindex="-1">Alert threshold <a class="header-anchor" href="#alert-threshold" aria-label="Permalink to &quot;Alert threshold&quot;">​</a></h3><p>The percentage of a project&#39;s budget at which VERA begins flagging it as a warning. Defaults to 80%. Once a project crosses this point it appears in burn rate alerts and the morning briefing.</p><hr><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="billable-non-billable" tabindex="-1">Billable / non-billable <a class="header-anchor" href="#billable-non-billable" aria-label="Permalink to &quot;Billable / non-billable&quot;">​</a></h3><p>Whether the time you&#39;re logging generates revenue for the business. Most client work is billable. Internal projects (training, admin, R&amp;D) are not. VERA knows which is which — you don&#39;t need to set this yourself.</p><h3 id="briefing" tabindex="-1">Briefing <a class="header-anchor" href="#briefing" aria-label="Permalink to &quot;Briefing&quot;">​</a></h3><p>The message VERA sends each weekday morning. It summarises your recent hours, your work plan for the week, and (for managers and owners) the health of your portfolio. See <a href="./morning-briefing.html">The morning briefing</a>.</p><h3 id="budget" tabindex="-1">Budget <a class="header-anchor" href="#budget" aria-label="Permalink to &quot;Budget&quot;">​</a></h3><p>The total hours a project is allowed to consume. Set by the owner; tracked by VERA against actual logged hours. Different from an envelope, which is an individual team member&#39;s share of that budget.</p><h3 id="burn-rate" tabindex="-1">Burn rate <a class="header-anchor" href="#burn-rate" aria-label="Permalink to &quot;Burn rate&quot;">​</a></h3><p>How quickly a project&#39;s hours are being used relative to what was planned. A project burning hours faster than expected will run out of budget before the deadline. Managers and owners see burn rate in their morning briefing and in retainer summaries.</p><hr><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="capacity" tabindex="-1">Capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to &quot;Capacity&quot;">​</a></h3><p>The total hours a team member has available in a given week, based on their standard working hours minus any approved time off. VERA shows a capacity bar for each team member in the morning briefing — how much is allocated versus how much is free. If someone is fully loaded, there&#39;s no room for additional work without removing something else first.</p><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>The company or entity a project is delivered for. Every project belongs to a client. Internal projects belong to a fictional &quot;Internal&quot; client so they still appear in reporting without inflating client numbers.</p><h3 id="contractor" tabindex="-1">Contractor <a class="header-anchor" href="#contractor" aria-label="Permalink to &quot;Contractor&quot;">​</a></h3><p>A freelancer or independent worker who operates inside VERA the same way a full-time employee does: they log their own time, receive envelopes, and their cost is calculated as hours × rate. The distinction between contractor and FTE is about payroll status — both use the system the same way. Different from a vendor, who delivers outcomes and does not log time at all.</p><h3 id="coverage-gap" tabindex="-1">Coverage gap <a class="header-anchor" href="#coverage-gap" aria-label="Permalink to &quot;Coverage gap&quot;">​</a></h3><p>A project with an active hours budget but no team members allocated to it — work is planned but nobody is assigned. VERA counts these in the alert summary so managers can spot resourcing gaps before work falls behind.</p><hr><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="deadline" tabindex="-1">Deadline <a class="header-anchor" href="#deadline" aria-label="Permalink to &quot;Deadline&quot;">​</a></h3><p>The date by which a project must be delivered. Visible to managers and owners — never shown to team members. Used to calculate whether a project is on pace to complete within budget.</p><h3 id="discipline" tabindex="-1">Discipline <a class="header-anchor" href="#discipline" aria-label="Permalink to &quot;Discipline&quot;">​</a></h3><p>A team member&#39;s area of expertise, such as Design, Development, or Strategy. Used for capacity planning and team reporting.</p><hr><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="employment-type" tabindex="-1">Employment type <a class="header-anchor" href="#employment-type" aria-label="Permalink to &quot;Employment type&quot;">​</a></h3><p>Classifies how a team member engages with the business. Three types: <strong>FTE</strong> (full-time employee), <strong>contractor</strong> (freelance, same system access as FTE), and <strong>vendor</strong> (deliverable-based, does not log time). Employment type determines how cost is calculated and whether the person appears in VERA&#39;s capacity planning.</p><h3 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to &quot;Envelope&quot;">​</a></h3><p>A work plan your manager has assigned to you on a specific project and task type. It defines how many hours you&#39;re expected to contribute. Your envelope shows up in your morning briefing as Plan / Logged / Remaining.</p><p>Envelopes are planning tools — they don&#39;t restrict you from logging time. You can log to any active project whether or not you have an envelope for it.</p><hr><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><h3 id="fixed-price" tabindex="-1">Fixed Price <a class="header-anchor" href="#fixed-price" aria-label="Permalink to &quot;Fixed Price&quot;">​</a></h3><p>A project type where the fee is agreed upfront regardless of hours spent. Revenue accrues proportionally as hours are logged (hours logged ÷ hours budget × contract value). Requires a contract value, hours budget, and deadline.</p><h3 id="fte" tabindex="-1">FTE <a class="header-anchor" href="#fte" aria-label="Permalink to &quot;FTE&quot;">​</a></h3><p>Full-time employee. Logs their own time in VERA; cost is calculated as hours × hourly rate.</p><hr><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h3><p>A traffic-light indicator for a project&#39;s delivery status — 🟢 on track, ⚠️ approaching the budget threshold, 🔴 over or critically underpaced. Visible in the morning briefing and portfolio summary.</p><hr><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><h3 id="internal-project" tabindex="-1">Internal project <a class="header-anchor" href="#internal-project" aria-label="Permalink to &quot;Internal project&quot;">​</a></h3><p>A project for overhead or non-client work: admin, training, R&amp;D, business development, and absence types (PTO, Sick, Leave). Internal projects have no budget targets or financial tracking.</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="leave" tabindex="-1">Leave <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;Leave&quot;">​</a></h3><p>An extended absence — parental, compassionate, unpaid, and so on. Requested through VERA and approved by a manager, the same way as <a href="./time-off.html">time off</a>.</p><h3 id="linear-track" tabindex="-1">Linear track <a class="header-anchor" href="#linear-track" aria-label="Permalink to &quot;Linear track&quot;">​</a></h3><p>The ideal burn-down line for a project — the total hours budget divided evenly across the total calendar days from start to deadline. On any given day, if your logged hours match the linear track, you&#39;re exactly on pace. If you&#39;re below it, you&#39;re behind; above it, you&#39;re ahead. VERA shows this as a progress indicator in the morning briefing, with 🟢 (ahead), ✅ (on track), ⚠️ (behind), and 🔴 (significantly behind).</p><h3 id="liability" tabindex="-1">Liability <a class="header-anchor" href="#liability" aria-label="Permalink to &quot;Liability&quot;">​</a></h3><p>A fixed payment commitment to a vendor: an agreed amount for a defined scope of work. Used in P&amp;L calculations in place of hours × rate for vendor engagements. Visible to owners and managers.</p><h3 id="log-logging" tabindex="-1">Log / logging <a class="header-anchor" href="#log-logging" aria-label="Permalink to &quot;Log / logging&quot;">​</a></h3><p>The act of recording your hours in VERA. &quot;Log 3 hours on Nike, design&quot; is all it takes. See <a href="./logging-time.html">Logging time</a>.</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h3><p>A project manager role. Managers see percentages (not dollar amounts) for the projects they own. They can approve time off, assign envelopes, and see burn rate and team capacity for their projects. See <a href="./roles.html">Your role in VERA</a>.</p><h3 id="morning-briefing" tabindex="-1">Morning briefing <a class="header-anchor" href="#morning-briefing" aria-label="Permalink to &quot;Morning briefing&quot;">​</a></h3><p>See <a href="#briefing">Briefing</a>.</p><hr><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="out-of-office-ooo" tabindex="-1">Out of Office (OOO) <a class="header-anchor" href="#out-of-office-ooo" aria-label="Permalink to &quot;Out of Office (OOO)&quot;">​</a></h3><p>A catch-all term for PTO, sick days, and leave. All three are recorded against protected internal projects. Team members submit a request; a manager approves and the hours are logged. Owners log their own time off directly without needing approval.</p><h3 id="out-of-envelope-time" tabindex="-1">Out-of-envelope time <a class="header-anchor" href="#out-of-envelope-time" aria-label="Permalink to &quot;Out-of-envelope time&quot;">​</a></h3><p>Hours logged to a project by someone who has no active envelope for it. This isn&#39;t blocked — envelopes are planning tools, not gates — but VERA flags it in the morning briefing so managers can see where unplanned work is happening and decide whether to formalise it with an envelope or adjust the plan.</p><h3 id="overbooking" tabindex="-1">Overbooking <a class="header-anchor" href="#overbooking" aria-label="Permalink to &quot;Overbooking&quot;">​</a></h3><p>When a team member has more hours allocated across projects than they have available in the week. Flagged with ⚠️ in the team capacity block of the morning briefing, with the number of hours over capacity shown. Overbooking doesn&#39;t stop anyone logging time — it&#39;s a signal to the manager to either adjust allocations or have a conversation about priorities.</p><h3 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h3><p>Full access. Owners see everything — dollar amounts, all projects, rates, and liabilities. They set project budgets, manage users, and control rates. See <a href="./roles.html">Your role in VERA</a>.</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="pace" tabindex="-1">Pace <a class="header-anchor" href="#pace" aria-label="Permalink to &quot;Pace&quot;">​</a></h3><p>The rolling burn trend for a project — how quickly hours are being used compared to the same period last week. VERA compares this week&#39;s hours against the previous two weeks to determine whether a project is accelerating, steady, or slowing down. Critical and warning pace signals appear in the morning briefing so managers can intervene before a project runs out of budget or falls dangerously behind.</p><h3 id="period" tabindex="-1">Period <a class="header-anchor" href="#period" aria-label="Permalink to &quot;Period&quot;">​</a></h3><p>A single billing cycle within a retainer — typically one month. Each period has its own hours budget and contract value. When a period closes, a new one opens. You log time against the current period, not the retainer as a whole.</p><h3 id="pm-project-manager" tabindex="-1">PM (Project Manager) <a class="header-anchor" href="#pm-project-manager" aria-label="Permalink to &quot;PM (Project Manager)&quot;">​</a></h3><p>The team member assigned responsibility for a project. PMs are notified when someone logs time to their project and are responsible for managing envelopes and monitoring burn rate.</p><h3 id="pro-bono" tabindex="-1">Pro Bono <a class="header-anchor" href="#pro-bono" aria-label="Permalink to &quot;Pro Bono&quot;">​</a></h3><p>A project type for client work delivered at no charge. No revenue is tracked — only hours. Requires an hours budget and deadline.</p><h3 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h3><p>The thing you&#39;re working on. Every hour you log goes to a project. Projects belong to clients (or to your own company, for internal work). Your manager or owner sets up projects — you just log to them.</p><h3 id="pto" tabindex="-1">PTO <a class="header-anchor" href="#pto" aria-label="Permalink to &quot;PTO&quot;">​</a></h3><p>Paid time off. Requested through VERA and approved by your manager before being recorded. You can&#39;t log PTO directly — it has to go through the approval process. See <a href="./time-off.html">Time off</a>.</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="rate" tabindex="-1">Rate <a class="header-anchor" href="#rate" aria-label="Permalink to &quot;Rate&quot;">​</a></h3><p>The hourly cost for a team member — what their time costs the business. Rates are versioned: a new rate takes effect from a given date without overwriting history. Visible to owners only.</p><h3 id="retainer" tabindex="-1">Retainer <a class="header-anchor" href="#retainer" aria-label="Permalink to &quot;Retainer&quot;">​</a></h3><p>An ongoing client engagement with a fixed fee per period (usually monthly). The client pays a set amount; the team delivers a set number of hours. VERA tracks how much of the current period has been used. See <a href="./projects.html">Projects and tasks</a>.</p><h3 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h3><p>Your permission level in VERA: Owner, Manager, or Team Member. Roles determine what data you can see and what actions you can take. See <a href="./roles.html">Your role in VERA</a>.</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sick-day" tabindex="-1">Sick day <a class="header-anchor" href="#sick-day" aria-label="Permalink to &quot;Sick day&quot;">​</a></h3><p>A day off due to illness. Unlike PTO, sick days don&#39;t require a formal request — your manager logs them on your behalf. See <a href="./time-off.html">Time off</a>.</p><h3 id="sprint" tabindex="-1">Sprint <a class="header-anchor" href="#sprint" aria-label="Permalink to &quot;Sprint&quot;">​</a></h3><p>A time-boxed delivery unit in an Agile project. Like a retainer period, each sprint has its own hours and contract value. When one sprint closes, the next opens.</p><h3 id="stale-item" tabindex="-1">Stale item <a class="header-anchor" href="#stale-item" aria-label="Permalink to &quot;Stale item&quot;">​</a></h3><p>An unresolved item that&#39;s been open longer than expected without being addressed. VERA counts stale items separately in the alert summary so managers can see when something has been sitting unresolved for too long and needs a decision.</p><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h3><p>For projects: <strong>active</strong>, <strong>completed</strong>, or <strong>cancelled</strong>. For retainer and Agile periods: <strong>planned</strong> (no revenue yet) or <strong>active</strong> (hours begin accruing revenue).</p><hr><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="t-m-time-materials" tabindex="-1">T&amp;M (Time &amp; Materials) <a class="header-anchor" href="#t-m-time-materials" aria-label="Permalink to &quot;T&amp;M (Time &amp; Materials)&quot;">​</a></h3><p>A project type where the client is billed for hours worked at a set rate. Revenue equals hours logged × billing rate. Requires an hours budget and deadline.</p><h3 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h3><p>The type of work you&#39;re doing within a project — Design, Development, Strategy, Admin, and so on. Each project has a specific set of tasks enabled for it. If you have a single task planned on a project, VERA applies it automatically when you log time. If you have multiple, they&#39;ll ask. To see which tasks are available: &quot;What tasks are on the Nike project?&quot;</p><h3 id="team-member" tabindex="-1">Team member <a class="header-anchor" href="#team-member" aria-label="Permalink to &quot;Team member&quot;">​</a></h3><p>The default role in VERA. Team members log their own time and see their own data. See <a href="./roles.html">Your role in VERA</a>.</p><h3 id="time-entry" tabindex="-1">Time entry <a class="header-anchor" href="#time-entry" aria-label="Permalink to &quot;Time entry&quot;">​</a></h3><p>A single record of work: a date, a project, a number of hours, and usually a task. Created when you log time. Can be edited or deleted if something&#39;s wrong.</p><hr><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><h3 id="unresolved-item" tabindex="-1">Unresolved item <a class="header-anchor" href="#unresolved-item" aria-label="Permalink to &quot;Unresolved item&quot;">​</a></h3><p>A flag VERA raises when something needs attention — a time-off conflict with an active envelope, a scheduling issue, or another situation that can&#39;t be resolved automatically. Visible in the morning briefing as a 🔴 block. Managers can ask VERA what the options are and choose how to resolve it.</p><hr><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="vendor" tabindex="-1">Vendor <a class="header-anchor" href="#vendor" aria-label="Permalink to &quot;Vendor&quot;">​</a></h3><p>A third party who delivers outcomes — a finished design, a developed feature — rather than selling their time by the hour. Vendors do not log time in VERA; the PM logs on their behalf. Their cost is governed by a fixed payment agreement, not hours × rate. Different from a contractor, who does operate inside the system.</p><hr><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="work-plan" tabindex="-1">Work plan <a class="header-anchor" href="#work-plan" aria-label="Permalink to &quot;Work plan&quot;">​</a></h3><p>See <a href="#envelope">Envelope</a>.</p>',135)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
